import 'dart:convert';

import 'package:flutter/services.dart' show AssetBundle, rootBundle;

/// The bundled publisher marks.
///
/// Which publisher has which artwork lives in `assets/publishers/logos.json`,
/// generated by `scripts/prepare_publisher_logos.py` from the reviewed files in
/// `assets/publishers/`. The app reads that map once, at startup, so a
/// directory row paints a local asset immediately — no request, no placeholder
/// flash, no dependency on the network to identify a newspaper.
///
/// A publisher with no reviewed artwork is simply absent from the map; the
/// widget then falls back to the publisher's own published icon and finally to
/// a monogram. Coverage is therefore visible in one place and testable, instead
/// of being implied by a pile of files.
class PublisherLogos {
  PublisherLogos._();

  static const String assetPath = 'assets/publishers/logos.json';

  static Map<String, String> _byId = const <String, String>{};
  static bool _loaded = false;

  /// Ids that have a verified, bundled mark.
  static Set<String> get bundledIds => _byId.keys.toSet();

  static int get count => _byId.length;
  static bool get isLoaded => _loaded;

  /// The asset path for a publisher, or `null` when none is bundled.
  static String? assetFor(String sourceId) => _byId[sourceId];

  /// Loads the manifest once. A missing or broken manifest leaves every lookup
  /// empty, which degrades to the remote/fallback chain rather than failing.
  static Future<void> load({AssetBundle? bundle, bool forceReload = false}) async {
    if (_loaded && !forceReload) return;
    _loaded = true;
    try {
      final String raw = await (bundle ?? rootBundle).loadString(assetPath);
      final Object? decoded = jsonDecode(raw);
      if (decoded is Map<String, dynamic>) {
        final Object? logos = decoded['logos'];
        if (logos is Map<String, dynamic>) {
          _byId = <String, String>{
            for (final MapEntry<String, dynamic> entry in logos.entries)
              if (entry.value is Map<String, dynamic> &&
                  (entry.value as Map<String, dynamic>)['file'] is String)
                entry.key: (entry.value as Map<String, dynamic>)['file'] as String,
          };
        }
      }
    } catch (_) {
      _byId = const <String, String>{};
    }
  }

  /// Test hook: install a map without touching the bundle.
  static void debugSet(Map<String, String> logos) {
    _byId = Map<String, String>.unmodifiable(logos);
    _loaded = true;
  }
}
